        let c4 = mf > F::cast_from(0.5_f64) && F::abs(b-c) < tol;
        let c5 = mf <= F::cast_from(0.5_f64) && F::abs(c-d) < tol;
        let do_bi = c1 || c2 || c3 || c4 || c5;
        s = select(do_bi, (a+b)*F::cast_from(0.5_f64), s);
        mf = select(do_bi, F::cast_from(1.0_f64), F::cast_from(0.0_f64));
        let fs = br89_obj::<F>(s, rhs);
        d = c; c = b; fc = fb;
        let root_left = fa*fs < F::cast_from(0.0_f64);
        b = select(root_left, s, b); fb = select(root_left, fs, fb);
        a = select(root_left, a, s); fa = select(root_left, fa, fs);
        let sw = F::abs(fa) < F::abs(fb);
        let ta = a; let tb = b; let tfa = fa; let tfb = fb;
        a = select(sw, tb, ta); fa = select(sw, tfb, tfa);
        b = select(sw, ta, tb); fb = select(sw, tfa, tfb);

