        let fs = br89_obj::<F>(s, rhs); d = c; c = b; fc = fb;
        let root_left = fa*fs < F::cast_from(0.0_f64);
        b = select(root_left, s, b); fb = select(root_left, fs, fb); a = select(root_left, a, s); fa = select(root_left, fa, fs);
